ALTER TABLE "preinspection_documents" ADD CONSTRAINT "preinspection_documents_association_chk" CHECK ((works_kind is null and associated_at is null and associated_by_user_id is null and association_fingerprint is null and association_reason is null) or (works_kind in ('extension', 'conversion') and associated_at is not null and associated_by_user_id is not null and association_fingerprint is not null and association_reason is not null));